from series import *
start('استاد قاضی','ghazi',[('استافیلوکوک','ساختار، بیماری و افتراق'),('کلامیدیا','چرخه و تظاهر چشمی، تناسلی و تنفسی'),('مایکوپلاسما','بدون دیواره و پنومونی آتیپیک'),('سودوموناس و آسینتوباکتر','فرصت‌طلبی، بیماری و مقاومت')])
A(1,'شناخت استاف و روش‌های دسته‌بندی',[3,4], 'استافیلوکوک‌ها کوکسی‌های گرم مثبت‌اند که معمولاً خوشه‌ای دیده می‌شوند. آزمون کاتالاز به افتراق آن‌ها از استرپتوکوک‌ها کمک می‌کند؛ برای شناسایی گونه به آزمون‌های بعدی نیاز داریم.',[
 ['ویژگی پایه','کوکسی گرم مثبتِ خوشه‌ای؛ اورئوس در متن بی‌هوازی اختیاری و دارای کلنی محدب طلایی/زرد معرفی شده است.'],['سه گونه','اورئوس، اپیدرمیدیس و ساپروفیتیکوس؛ دو نام آخر عموماً کواگولاز منفی در مسیر درسی'],['کاتالاز','مثبت به سوی استاف؛ منفی به سوی استرپ در چارچوب جزوه'],['بایوتایپ','ویژگی‌های زیست‌شیمیایی مانند کاتالاز، مصرف مانیتول و نوکلئاز'],['سروتایپ و منشأ','واکنش آنتی‌ژنی؛ و منشأ جداسازی دو ویژگی متفاوت هستند.'],['فاژتایپ','الگوی حساسیت به فاژ؛ ناحیهٔ شفاف شکل صفحهٔ ۴ علامت لیز است.'],['آنتی‌بیوتایپ و روش مولکولی','الگوی حساسیت دارویی با شناسایی قطعهٔ ژنتیکی یک چیز نیست؛ یک عامل می‌تواند چند برچسب هم‌زمان داشته باشد.'] ],
 'خوشه و گرم، سپس کاتالاز و افتراق اختصاصی؛ هر روش یک محور دارد.',
 [('بایوتایپ، سروتایپ و فاژتایپ را مقایسه کنید.','اولی ویژگی زیست‌شیمیایی، دومی الگوی آنتی‌ژنی و سومی الگوی حساسیت به فاژ است؛ این دسته‌ها می‌توانند همپوشان باشند.',['سه معیار','همپوشانی']),('چرا کاتالاز همهٔ مسیر تشخیص نیست؟','در این درس شاخهٔ استاف/استرپ را جدا می‌کند؛ برای گونه به کواگولاز و آزمون‌های دیگر نیاز است.',['شاخه','گونه','آزمون همراه'])])
A(1,'ساختارها، آنزیم‌ها و سم‌های استاف',[4,5,6], 'عوامل بیماری‌زایی استاف کارهای متفاوتی دارند: بعضی اتصال یا فرار از دفاع را آسان می‌کنند، بعضی به گسترش در بافت کمک می‌کنند و سم‌ها به سلول یا بافت هدف آسیب می‌زنند.',[
 ['کپسول و پروتئین A','کپسول به فرار از فاگوسیتوز کمک می‌کند؛ پروتئین A با اتصال به بخش Fc پادتن IgG، اپسونیزاسیون را مختل می‌کند.'],['پپتیدوگلیکان','پل پنج‌گلیسینی در استاف اورئوس، اسید تیکوئیک و پروتئین‌های سطحی ذکر شده‌اند.'],['کواگولاز و کاتالاز','اولی لختهٔ فیبرینی در شرح منبع؛ دومی تجزیهٔ پراکسید هیدروژن و حفاظت اکسیداتیو'],['گسترش','استافیلوکیناز تجزیهٔ فیبرین؛ هیالورونیداز اثر بر مادهٔ بین‌بافتی؛ نوکلئاز اثر بر اسید نوکلئیک؛ لیپاز اثر بر چربی'],['مقاومت','پنی‌سیلیناز زیرگروه بتالاکتاماز در این درس'],['سم‌ها','انتروتوکسین روده‌ای؛ اکسفولیاتیو/SSSS پوستی؛ TSST-1؛ سم سلولی شامل همولیزین و لوکوسیدین در فهرست'],['معیار اهمیت','صرف تعداد عوامل برابر شدت بیماری نیست؛ نقش و زمینه اهمیت دارد.'] ],
 'دفاع: کپسول و A؛ گسترش: تجزیهٔ سد؛ سم: اثر بر بافت هدف.',
 [('سه عامل گسترش را با هدفشان بنویسید.','هیالورونیداز با مادهٔ بین‌بافتی، استافیلوکیناز با فیبرین و نوکلئاز با اسید نوکلئیک مرتبط‌اند؛ این گسترش، حرکت تاژکی نیست.',['سه نام','هدف','گسترش از تحرک جدا']),('کپسول و پروتئین A چگونه متفاوت‌اند؟','کپسول تعامل با فاگوسیت و پروتئین A کار پادتن را مختل می‌کند؛ دو مسیر دفاعی‌اند.',['فاگوسیت','پادتن'])])
A(1,'بیماری استافی: سم غذایی یا عفونت بافتی',[6,7,8], 'در مسمومیت غذایی استاف، سم ازپیش‌ساخته وارد بدن می‌شود. در عفونت پوست، استخوان یا قلب، خود باکتری در بافت حضور و فعالیت دارد؛ این تفاوت، تظاهر بیماری را توضیح می‌دهد.',[
 ['غذایی','سمِ مقاوم نسبی شروع کوتاه و برجستگی تهوع/استفراغ؛ نقش واگ ذکر شده است.'],['زردزخم','ضایعهٔ سطحی و دلمه؛ اورئوس و گاه استرپ در متن؛ تصویر صفحهٔ ۷ نمونهٔ ظاهر است.'],['فولیکول و پلک','فولیکولیت درگیری فولیکول؛ گل‌مژه نمونهٔ پلک؛ فورونکل و کاربونکل برای درگیری عمیق‌تر/پیوسته آمده‌اند.'],['اطراف ناخن و زخم','پارونیشیا؛ زخم و تروما و دیابت در زمینهٔ عفونت'],['دوردست','اندوکاردیت، پنومونی و استئومیلیت؛ در استخوان ورود مستقیم یا گسترش خونی دو مثال‌اند.'] ],
 'سم غذایی: اثر سم؛ زخم و خون: عامل و بافت. مو، پلک، ناخن را جدا نام ببر.',
 [('مسمومیت و عفونت غذایی چه فرقی دارند؟','در تعریف این جزوه، مسمومیت با سمِ دریافت‌شده رخ می‌دهد؛ عفونت با ورود عامل و فعالیت آن در بدن. کوتاهی شروع غذایی استاف به سم ازپیش‌ساخته مرتبط شده است.',['عامل ورودی','سم','زمان']),('استئومیلیت مستقیم و ثانویه را مقایسه کنید.','ورود عامل به استخوان در آسیب یا جراحی، مستقیم است؛ رسیدن از محل دیگر با خون، ثانویه در توضیح متن.',['ورود مستقیم','خون','محل اولیه'])])
A(1,'افتراق گونه و مقاومت استاف',[8,9,10], 'کواگولاز به افتراق اورئوس و نووبیوسین به مقایسهٔ دو گونهٔ کواگولاز منفی کمک می‌کند. مقاومت ناشی از بتالاکتاماز با سازوکار MRSA یکسان نیست.',[
 ['اورئوس در مسیر جزوه','کاتالاز مثبت، کواگولاز مثبت، DNase و مصرف مانیتول از سرنخ‌ها؛ همولیز به‌تنهایی قطعی نیست.'],['مانیتول‌سالت','نمک، انتخاب‌گری را توضیح می‌دهد؛ تخمیر و اسید، تغییر رنگ را. این دو اثر یکی نیستند.'],['نووبیوسین','ساپروفیتیکوس مقاوم؛ اپیدرمیدیس حساس، در مقایسهٔ دو گونهٔ جزوه'],['پیامد گونه‌ها','ساپروفیتیکوس با عفونت ادراری زن جوان؛ اپیدرمیدیس فلور پوست و عفونت وسیله/دریچهٔ مصنوعی'],['بتالاکتاماز و MRSA','تخریب دارو با مقاومت به متی‌سیلین یک مکانیسم واحد نیست؛ تعریف MRSA اورئوس مقاوم به متی‌سیلین است.'],['وانکومایسین','در متن برای موارد منتخب مطرح شده؛ اثر بر گرم مثبت و نگرانی مقاومت ذکر شده است.'] ],
 'اورئوس کواگولاز؛ دو منفی را با نووبیوسین مقایسه کن.',
 [('دو استاف کواگولاز منفی را چگونه مقایسه می‌کنید؟','ساپروفیتیکوس با عفونت ادراری زن جوان و مقاومت نووبیوسین؛ اپیدرمیدیس با فلور پوست، وسیلهٔ مصنوعی و حساسیت نووبیوسین در متن.',['محل','پیامد','آزمون']),('انتخاب‌گری محیط و تخمیر چه تفاوتی دارند؟','نمک رشد گروه‌ها را متفاوت می‌کند؛ مصرف مانیتول با تولید اسید نتیجهٔ افتراقی می‌دهد.',['نمک','قند','اسید'])])
A(2,'کلامیدیا: وابستگی به میزبان و دو شکل',[11,12,13,15], 'کلامیدیا باکتریِ وابسته به سلول میزبان است. جسم ابتدایی یا EB آغازگر عفونت و جسم مشبک یا RB شکل تکثیرشوندهٔ درون سلول است.',[
 ['هویت','دارای دی‌ان‌ای، آر‌ان‌ای و دستگاه ساخت پروتئین است. برای تکثیر به سلول میزبان وابسته است؛ پس وابستگی درون‌سلولی، آن را ویروس نمی‌کند.'],['ATP ترانسلوکاز؛ تأکید منبع','انتقال نوکلئوتیدهای میزبان در تأمین نیازهای متابولیک نقش دارد؛ وابستگی به میزبان را نباید به نبود مطلق همهٔ مسیرهای تولید انرژی تعبیر کرد.'],['جسم ابتدایی؛ EB','کوچک‌تر، کم‌فعال‌تر و آغازگر عفونت؛ در خارج سلول تکثیر نمی‌کند. شبیه‌سازی با اسپور فقط کمک توصیفی است.'],['جسم مشبک؛ RB','بزرگ‌تر و فعال‌تر در ساخت پروتئین و تقسیم داخل سلول'],['MOMP','پروتئین عمدهٔ غشای خارجی؛ در اتصال و تفاوت‌های آنتی‌ژنی نقش دارد.'],['چرخه','اتصال و ورود EB، تبدیل به RB، تکثیر، تولید دوبارهٔ EB و خروج؛ هم‌زمانی دو فرم در یک سلول ممکن است.'] ],
 'ابتدایی برای ورود؛ مشبک برای تکثیر؛ دوباره ابتدایی برای انتقال.',
 [('EB و RB را مقایسه کنید.','EB کوچک و آغازگر عفونت با فعالیت کمتر است؛ RB بزرگ‌تر و تکثیرشوندهٔ درون‌سلولی. خارج سلول تکثیر رخ نمی‌دهد.',['اندازه','نقش','جای تکثیر']),('چرخه را مرتب بنویسید.','اتصال با عامل سطحی، ورود EB، تبدیل به RB، تقسیم و سپس تبدیل بخشی به EB و خروج برای سلول دیگر.',['ورود','تبدیل','تکثیر','بازگشت و خروج'])])
A(2,'تراکوماتیس: چشم، عفونت تناسلی و نوزاد',[13,14,15,16,17], 'سرووارهای مختلف کلامیدیا تراکوماتیس بیماری‌های متفاوتی ایجاد می‌کنند. تراخم، عفونت تناسلی و عفونت نوزادی را باید با سرووار و مسیر انتقالشان شناخت.',[
 ['A، B و C','تراخم و انتقال ترشحات چشمی؛ سطح بهداشت در منبع برجسته است.'],['D تا K','عفونت تناسلی و امکان انتقال هنگام تولد با کونژکتیویت یا پنومونی نوزاد؛ هر عفونت چشمی نوزاد تراخم نیست.'],['LGV','لنفوگرانولوم ونروم، مرتبط با سرووارهای L1 تا L3؛ از عفونت‌های D تا K جداست.'],['بالارونده','سرویکس، رحم و لوله‌ها در زنان؛ مجرا، پروستات و اپیدیدیم در مردان در توضیح منبع'],['پیامدها','سرویسیت/اورتریت، درد لگن، PID، ناباروری، حاملگی خارج رحم و پیامد بارداری در فهرست'],['STI و STD','STI به عفونت منتقلهٔ جنسی اشاره دارد که ممکن است بی‌علامت باشد؛ STD بر بیماری و تظاهر آن تأکید دارد. نبود علامت، احتمال انتقال یا آسیب را منتفی نمی‌کند.'],['SAFE','جراحی، آنتی‌بیوتیک، پاکیزگی صورت و بهبود محیط؛ نام راهبرد مطرح‌شدهٔ تراخم'] ],
 'A–C چشم؛ D–K تناسلی و نوزاد؛ بی‌علامتی را برابر بی‌آسیبی ندان.',
 [('چرا عفونت نوزاد را تراخم نمی‌نامیم؟','در جزوه انتقال D–K هنگام تولد با کونژکتیویت/پنومونی جدا از تراخم A–C است؛ محل چشم به‌تنهایی نام سرووار یا بیماری را تعیین نمی‌کند.',['سرووار','راه','چشم کافی نیست']),('عفونت بالارونده چه پیامدی دارد؟','گسترش از مخاط تحتانی به سرویکس و لوله‌ها می‌تواند با التهاب، آسیب و ناباروری یا حاملگی خارج رحم مرتبط شود؛ در مردان مجرا و اپیدیدیم مطرح‌اند.',['مسیر','التهاب','پیامد'])])
A(2,'گونه‌های تنفسی و تشخیص کلامیدیا',[14,15,16,17,18], 'کلامیدیا پسیتاسی بیشتر با تماس با پرندگان و کلامیدیا پنومونیه با عفونت تنفسی انسان مرتبط است. آزمون مولکولی وجود عامل و سرولوژی پاسخ پادتنی میزبان را بررسی می‌کند.',[
 ['تراکوماتیس در جدول','میزبان انسان؛ کونژکتیویت، پنومونی نوزاد، عفونت تناسلی و LGV؛ انکلوزیون گلیکوژن‌دار و حساسیت سولفونامیدی «مثبت» در جدول'],['پسیتاسی','پرندگان و نیز دام/گربه در جدول؛ پنومونی و اندوکاردیت؛ دو ویژگی گلیکوژن و سولفونامید «منفی» در همان جدول'],['پنومونیه؛ TWAR','میزبان انسان؛ برونشیت و پنومونی. در جدول جزوه، گلیکوژن انکلوزیون و حساسیت سولفونامیدی منفی ثبت شده‌اند.'],['اصل تشخیص','عامل داخل سلول است؛ شواهد سلولی/مولکولی از پادتن تماس قبلی جدا می‌شوند. سلول McCoy و مدل‌های نام‌برده در جزوه، توضیح وابستگی‌اند.'],['مقایسهٔ پنومونی','تیپیک ناگهانی و با خلط برجسته؛ آتیپیک تدریجی‌تر و با سرفهٔ خشک مطرح می‌شود.'] ],
 'پسیتاسی و پرنده؛ پنومونیه و تنفس؛ تراکوماتیس و چشم/تناسلی.',
 [('سه گونه را با میزبان و بیماری مقایسه کنید.','تراکوماتیس انسان و چشم/تناسلی/نوزاد؛ پسیتاسی با پرندگان و بیماری تنفسی مشترک انسان و حیوان؛ پنومونیه انسان و بیماری تنفسی.',['سه نام','میزبان','محل']),('چرا پادتن برای نسبت‌دادن آترواسکلروز کافی نیست؟','تماس، واکنش متقاطع و همبستگی از علت‌بودن جدا هستند؛ خود جدول رابطه را با سؤال مطرح می‌کند.',['همبستگی','واکنش متقاطع','علت'])])
A(3,'مایکوپلاسما: نبود دیواره و گونه‌های مهم',[19,20,21], 'مایکوپلاسما دیوارهٔ پپتیدوگلیکانی ندارد؛ به همین دلیل چندشکلی است و بتالاکتام‌ها هدف معمول خود را در آن ندارند. این باکتری برخلاف کلامیدیا الزاماً درون‌سلولی نیست.',[
 ['ساختار','بدون دیوارهٔ پپتیدوگلیکانی، چندشکلی، غشای دارای استرول و ژنوم کوچک در چارچوب متن'],['تفاوت با کلامیدیا','وابستهٔ اجباری درون‌سلولی معرفی نشده و امکان رشد مستقل روی محیط مناسب دارد؛ PPLO نام برده شده است.'],['پنومونیه','راه تنفسی فوقانی/تحتانی، پنومونی آتیپیک و تجمع در فضای بسته/مدرسه'],['هومینیس و ژنیتالیوم','عوامل مرتبط با دستگاه ادراری–تناسلی؛ هومینیس در بعضی عفونت‌های لگنی و پس از زایمان و ژنیتالیوم در عفونت‌های منتقلهٔ جنسی مطرح است.'],['پنترانس','نام گونه‌ای که در جدول در ارتباط با افراد مبتلا به HIV آمده است؛ این همراهی به‌تنهایی رابطهٔ علّی را اثبات نمی‌کند.'],['اوره‌آپلاسما اوره‌آلیتیکوم','نیاز به اوره و اورتریت غیرگنوکوکی؛ در جدول شیوع «بسیار شایع» نوشته شده است.'],['درخت صفحهٔ ۲۰','ردهٔ Mollicutes، راستهٔ Mycoplasmatales؛ Mycoplasmataceae شامل Mycoplasma و Ureaplasma؛ شاخه‌های گیاهی Spiroplasmataceae و حیوانی Acholeplasmataceae و Anaeroplasmataceae هم در شکل آمده‌اند.'] ],
 'دیواره نیست: شکل ثابت و هدف دیواره‌ای هم نیست؛ غشای استرولی را به‌خاطر بسپار.',
 [('چرا بتالاکتام برای این بحث هدف مناسبی ندارد؟','مایکوپلاسما دیوارهٔ پپتیدوگلیکانی ندارد؛ پس داروی هدف‌گیرندهٔ آن ساختار، هدف معمول خود را در این عامل ندارد.',['نبود ساختار','هدف دارو']),('تفاوت اصلی با کلامیدیا چیست؟','در متن، کلامیدیا تکثیر وابسته به سلول زنده دارد؛ مایکوپلاسما بدون دیواره است ولی تکثیر مستقل در شرایط تغذیه‌ای مناسب ممکن است.',['درون‌سلولی','دیواره','تکثیر'])])
A(3,'پنومونی آتیپیک و آزمون سرد',[18,20,21], 'مایکوپلاسما پنومونیه می‌تواند پنومونی با شروع تدریجی و سرفهٔ خشک ایجاد کند. آزمون سرد، تجمع گلبول‌های قرمز را نشان می‌دهد و به‌تنهایی اثبات اختصاصی عفونت نیست.',[
 ['بالینی','تب، علائم تنفسی و سرفهٔ خشک با شروع تدریجی در شرح پنومونی آتیپیک؛ راه‌رفتن بیمار به معنی کم‌خطر بودن همهٔ موارد نیست.'],['مولکولی','وجود مادهٔ ژنتیکی عامل؛ در جزوه PCR برجسته شده است.'],['سرولوژی','پاسخ پادتنی و سابقهٔ تماس می‌تواند تفسیر را پیچیده کند؛ رد همهٔ کاربردها تعمیم است.'],['آگلوتیناسیون سرد','پادتن IgM و تجمع گلبول قرمز وابسته به دما در شکل؛ تجمع را با لختهٔ فیبرینی یکی نکن.'],['دارو در متن','ماکرولیدها مانند اریترومایسین/آزیترومایسین و تتراسایکلین برای هدف ساخت پروتئین نام برده شده‌اند؛ الگوریتم تجویز نیست.'] ],
 'مولکولی، ژن را؛ سرولوژی، پادتن را؛ آزمون سرد، تجمع را نشان می‌دهد.',
 [('آزمون سرد چه پدیده‌ای را نشان می‌دهد؟','تجمع گلبول قرمز به واسطهٔ پادتن مرتبط با دما؛ خودِ دیدن میکروب یا لخته‌شدن فیبرینی نیست و به‌تنهایی تشخیص اختصاصی کامل نمی‌دهد.',['IgM','تجمع','محدودیت']),('چرا فقط تابلوی تیپیک/آتیپیک کافی نیست؟','الگوها همپوشانی دارند؛ تشخیص عامل به زمینه و شواهد اختصاصی نیاز دارد، نه فرض خفیف یا شدیدبودن اجباری.',['همپوشانی','عامل','شواهد'])])
A(4,'سودوموناس: هویت، رنگدانه و جدول‌های منبع',[23,24], 'سودوموناس آئروژینوزا باسیل گرم منفی و اکسیداز مثبتِ محیط‌های مرطوب است. پیووردین و پیوسیانین دو رنگدانهٔ مهم آن‌اند که رنگ و نقش متفاوتی دارند.',[
 ['هویت','باسیل گرم منفی، هوازی و متحرک با تاژک قطبی؛ اکسیداز مثبت در افتراق درسی با انتروباکتری‌ها'],['محیط','آب و خاک و ناحیهٔ مرطوب؛ فرصت‌طلب و عامل مهم بیمارستانی؛ کلنی از خشک/خشن تا موکوئید متفاوت است.'],['پیووردین','زرد و فلورسنت در شرح تشخیصی'],['پیوسیانین','آبی/سبزآبی؛ اثر بر دفاع مژکی در توضیح متن؛ ترکیب رنگدانه‌ها به سبزی نسبت داده شده است.'],['بو و همولیز','بوی میوه‌ای/انگور ترش و همولیز متغیر، سرنخ توصیفی‌اند.'] ],
 'باسیل و اکسیداز؛ محیط مرطوب؛ زرد فلورسنت و آبی را جدا نام ببر.',
 [('دو رنگدانه را مقایسه کنید.','پیووردین زرد و با فلورسانس تشخیصی مطرح است؛ پیوسیانین آبی/سبزآبی و با آسیب دفاع مژکی ربط دارد.',['نام','رنگ','نقش']),('چرا صرف رنگ کافی نیست؟','ظاهر کلنی متغیر است و سرنخ باید با گرم، شکل، اکسیداز و زمینه تفسیر شود.',['تغییرپذیری','ویژگی همراه'])],more=D('تمام گروه‌های جدول rRNA صفحهٔ ۲۳',T(['گروه','نام‌ها با نگارش منبع'],[['I فلورسنت','P. aeruginosa، P. fluorescens، P. putida'],['I غیرفلورسنت','P. stutzeri، P. mendocina'],['II','Burkholderia pseudomallei، B. mallei، B. cepacia، Cupriavidus، Delftia، Pandoraea، Ralstonia pickettii'],['III','Comamonas و Acidovorax'],['IV','Brevundimonas'],['V','Stenotrophomonas maltophilia']]))+D('جدول اولویت مقاومت در خود جزوه',T(['رده در تصویر','موارد'],[['بحرانی','آسینتوباکتر بومانی و سودوموناس مقاوم به کارباپنم؛ انتروباکتریاسه مقاوم به کارباپنم/سفالوسپورین'],['بالا','انتروکوک فسیوم مقاوم به وانکومایسین؛ اورئوس مقاوم متی‌سیلین/وانکومایسین؛ هلیکوباکتر مقاوم کلاریترومایسین؛ کمپیلوباکتر و سالمونلا مقاوم فلوروکینولون؛ گنوکوک مقاوم سفالوسپورین/فلوروکینولون'],['متوسط','پنوموکوک غیرحساس به پنی‌سیلین؛ هموفیلوس مقاوم آمپی‌سیلین؛ شیگلا مقاوم فلوروکینولون']])) )
A(4,'سودوموناس: میزبان و محل‌های بیماری',[25,26], 'سوختگی، اختلال پاک‌سازی راه هوایی و وسایل پزشکی می‌توانند زمینهٔ عفونت سودوموناسی را فراهم کنند. محل درگیری، از قرنیه تا ریه و خون، تظاهر بیماری را تعیین می‌کند.',[
 ['افراد در خطر','سوختگی، دیابت همراه با زخم، بستری، نقص ایمنی و سیستیک‌فیبروزیس از زمینه‌های مهم مطرح در جزوه‌اند.'],['چشم','کراتیت، هیپوپیون و پان‌افتالمیت؛ لنز/آسیب قرنیه در مثال و اهمیت پیشرفت سریع'],['گوش','گوش خارجی و شکل‌های شدیدتر؛ فرد مستعد و محیط آب در متن'],['خون و پوست','باکتریمی و اکتیمای گانگرنوزوم؛ شکل صفحهٔ ۲۶ نمای آسیب پوستی را نشان می‌دهد.'],['قلب و ادرار','اندوکاردیت و وسایل/دریچه؛ UTI با زمینهٔ کاتتر و بیمارستان'],['ریه','عفونت جامعه یا بیمارستان؛ CF و مخاط غلیظ، کاهش پاک‌سازی و استقرار'],['استخوان و گوارش','ورود مستقیم/انتشار خونی؛ تب شانگهای در سن پایین، با تأکید پرسش گذشته در منبع'] ],
 'سد آسیب‌دیده، پاک‌سازی ضعیف و وسیلهٔ خارجی؛ محل، پیامد را تعیین می‌کند.',
 [('چرا سوختگی و CF هر دو زمینه‌سازند؟','سوختگی سد پوست را برمی‌دارد؛ CF پاک‌سازی راه هوایی را مختل و مخاط غلیظ را به زمینهٔ استقرار تبدیل می‌کند؛ دو مسیر متفاوتِ فرصت‌طلبی‌اند.',['پوست','مخاط','دو مسیر']),('باکتریمی و ضایعهٔ پوستی چگونه مرتبط‌اند؟','در متن، حضور عامل در خون می‌تواند با ضایعهٔ اکتیمای گانگرنوزوم همراه شود؛ خود باکتریمی را با هر راش یکسان نمی‌کنیم.',['خون','نام ضایعه','قید'])])
A(4,'بیماری‌زایی و مقاومت سودوموناس',[27,28,29], 'سودوموناس با عوامل اتصال، آنزیم‌های تخریب‌کننده و سم‌ها به میزبان آسیب می‌زند. نفوذ کم پوشش، پمپ‌های خروج و آنزیم‌های غیرفعال‌کننده نیز به مقاومت دارویی کمک می‌کنند.',[
 ['اتصال','پیلی، تاژک و عوامل غیرپیلی؛ آلژینات در شرح کپسول/ماتریکس به اتصال و حفاظت مرتبط است.'],['فرار از دفاع','پیوسیانین و اختلال مژک؛ آلکالین پروتئاز و اثر بر کمپلمان'],['LPS','IL-1، IL-6 و TNF-α در توضیح التهاب، تب و اختلال عروقی'],['اگزوتوکسین A','قسمت اتصال و قسمت فعال؛ اختلال EF2 و توقف ساخت پروتئین در شرح منبع؛ اگزوتوکسین S نیز نام برده شده است.'],['آنزیم‌ها','LasA، LasB، الاستاز و فسفولیپاز؛ تخریب بافت/عروق و غشا در متن'],['مقاومت','نفوذ کم، پمپ خروج دارو و آنزیم غیرفعال‌کننده؛ ذاتی و اکتسابی می‌توانند همراه باشند.'],['آنتی‌بیوگرام','برای انتخاب متناسب اهمیت دارد؛ نام درمان تجربی در متن به فوریت بالینی مربوط است، نه نسخهٔ ثابت.'] ],
 'ورود کم، خروج زیاد و داروی تخریب‌شده؛ سم A را به EF2 وصل کن.',
 [('سه محور مقاومت را شرح دهید.','دارو کمتر وارد می‌شود، با پمپ بیرون رانده می‌شود یا توسط آنزیم غیرفعال می‌گردد. این‌ها از آسیب ناشی از سم جدا هستند.',['نفوذ','خروج','غیرفعال‌سازی']),('سم A چگونه آسیب می‌دهد؟','اتصال به سلول و اثر بخش فعال بر EF2، ساخت پروتئین را مختل می‌کند و به آسیب/مرگ سلول ربط دارد.',['اتصال','EF2','پروتئین'])],more=D('فهرست داروییِ آموزشی صفحهٔ ۲۹',P('رمز CAMP FIRE در منبع برای کارباپنم، آمینوگلیکوزید، مونوباکتام، پلی‌میکسین، فلوروکینولون، سفالوسپورین و پنی‌سیلین وسیع‌الطیف آمده است؛ مثال‌ها: ایمیپنم/مروپنم/دوریپنم، کانامایسین/جنتامایسین/توبرامایسین، آزترئونام، کلیستین، سیپروفلوکساسین/لووفلوکساسین، سفتازیدیم/سفپیم و پیپراسیلین/تیکارسیلین. سفیدروکول و مهارکننده‌های بتالاکتاماز هم نام برده شده‌اند. همه، فهرست همان جزوه‌اند و فعالیت همگانی علیه هر جدایه را ثابت نمی‌کنند.')))
A(4,'آسینتوباکتر و پیشگیری بیمارستانی',[29,30], 'آسینتوباکتر و سودوموناس هر دو در عفونت‌های بیمارستانی مهم‌اند. کوکوباسیل و اکسیداز منفی بودن آسینتوباکتر، از سرنخ‌های افتراق آن از سودوموناس است.',[
 ['شباهت','گرم منفی، هوازی، کاتالاز مثبت و مقاومت بالا در متن؛ عوامل فرصت‌طلب بیمارستانی'],['افتراق','آسینتوباکتر کوکوباسیل و اکسیداز منفی؛ سودوموناس باسیل و اکسیداز مثبت در جدول درسی'],['گونه‌ها','بومانی و لوفی در منبع برجسته‌اند؛ تعداد ثابت گونه‌ها و نسبت‌ها را دادهٔ تاریخی جزوه بدان.'],['محیط و وسایل','سطوح، دست و تجهیزات مانند ونتیلاتور/دیالیز؛ تماس و انتقال زنجیره‌ای مهم‌اند.'],['نام محیط‌ها','کروم‌آگار و لیدز برای بحث آسینتوباکتر؛ ستریماید برای سودوموناس در منبع؛ اصل انتخاب/افتراق مهم است.'],['اصول کنترل','بهداشت دست، رسیدگی به محیط و وسیله و مصرف سنجیدهٔ آنتی‌بیوتیک در متن'],['داروهای نام‌برده','ایمیپنم، پلی‌میکسین، تایجی‌سایکلین و برخی آمینوگلیکوزیدها؛ انتخاب وابسته به حساسیت، نه دستور واحد'] ],
 'آسینتو: کوکوباسیل، اکسیداز منفی؛ هر دو در زنجیرهٔ بیمارستان مهم‌اند.',
 [('دو عامل را در سه محور مقایسه کنید.','هر دو گرم منفی و فرصت‌طلب بیمارستانی‌اند؛ سودوموناس باسیل و اکسیداز مثبت، آسینتوباکتر کوکوباسیل و اکسیداز منفی است؛ مقاومت در هر دو اهمیت دارد.',['شباهت','شکل','اکسیداز']),('چرا کنترل فقط انتخاب یک دارو نیست؟','انتقال با دست، محیط و تجهیزات و انتخاب مقاومت نیز نقش دارند؛ بهداشت و مدیریت مصرف کنار درمان قرار می‌گیرند.',['انتقال','تجهیزات','مصرف دارو'])])
mixed=[Q('یک کوکسی گرم مثبت را در مسیر استافی چگونه بررسی می‌کنید؟','شکل و گرم، کاتالاز و سپس کواگولاز؛ برای دو گونهٔ منفی، مقایسهٔ نووبیوسین و زمینهٔ بالینی در این جزوه مطرح است.',['گرم','کاتالاز','کواگولاز','افتراق'],[3,8,9]),Q('کلامیدیا و مایکوپلاسما را از نظر دیواره، وابستگی و درمان مفهومی مقایسه کنید.','کلامیدیا دو شکل EB و RB و چرخهٔ وابسته به سلول میزبان دارد. مایکوپلاسما دیوارهٔ پپتیدوگلیکانی ندارد، اما روی محیط مناسب مستقل از سلول میزبان رشد می‌کند. نبود دیواره در مایکوپلاسما، نبود هدف معمول برای بتالاکتام‌ها را توضیح می‌دهد.',['دیواره','تکثیر','فرم','هدف'],[11,12,13,19,21]),Q('چرا ظاهر مشابه عفونت، درمان یکسان را ثابت نمی‌کند؟','عامل، محل، میزبان و حساسیت متفاوت‌اند؛ نمونهٔ این فایل پنومونی‌های با عوامل مختلف و دو فرصت‌طلب بیمارستانی‌اند.',['عامل','میزبان','حساسیت'],[18,21,26,29,30]),Q('گسترش بافتی، حرکت و مقاومت را تفکیک کنید.','گسترش با تجزیهٔ سد ممکن می‌شود؛ حرکت به ساختاری مانند تاژک مربوط است؛ مقاومت با نفوذ/خروج/تخریب دارو. این سه اصطلاح مترادف نیستند.',['سه تعریف','مثال متناسب'],[6,27,28])]
source=[Q('چرا کلامیدیا انگل اجباری درون‌سلولی معرفی می‌شود؟','کلامیدیا برای تکمیل چرخهٔ رشد و تکثیر به محیط درون سلول و مواد فراهم‌شده توسط میزبان وابسته است. این وابستگی با دستگاه انتقال نوکلئوتید و محدودیت‌های متابولیک آن ارتباط دارد.',['میزبان','انرژی','قید'],[11],'پرسش صریح جزوه'),Q('چگونه از ATP میزبان استفاده می‌کند؟','پاسخ خود منبع ATP ترانسلوکاز است؛ نام انتقال‌دهنده را از نقش عامل چسبندگی MOMP جدا بنویس.',['ترانسلوکاز','انرژی','تفکیک اتصال'],[11],'پرسش صریح جزوه')]
